// lib/gta/blocks.js — per-block city generators for the endless GTA
// cities (Wave 4, Nov 18, 2026).
//
// Merlin: "Make all 3d worlds infinite space too please" — like Mars 2.
// The home cities were generated by ONE sequential RNG stream over a
// fixed grid (generateCity / generateTown / generateBabelDistrict),
// so their buildings cannot be re-derived per block — the home region
// keeps its original generator verbatim, byte-identical. The
// OUTSKIRTS grow from these block-local generators instead: the seed
// is a hash of the block coordinates (lib/infinite/streaming.js), so
// the same block always grows the same buildings on every phone, and
// each block follows the SAME law its home generator uses for one
// block (same district lookup, same counts, same size ranges, same
// skips) — the city just keeps going.
//
// Pure, node-safe: no three.js, no DOM, no @/ alias — the scenes and
// the headless tests share these numbers.

import { chunkBounds, hashString32, mulberry32 } from '../infinite/streaming.js';

// --- Mega City ----------------------------------------------------------
// Mirrors app/mega-city/city.js generateCity, one block at a time.
// districts: [{ id, cx, cz, r, minH, maxH, color }] in priority order;
// outer: { minH, maxH, color, id } for blocks outside every district;
// water: { cx, cz, r } | null — blocks inside stay empty (the harbor).
export function generateCityBlock(bx, bz, opts) {
  const { seed = 1337, blockSize, roadWidth, districts, outer, water } = opts;
  const rand = mulberry32(hashString32(`mega-city:block:${bx}:${bz}:${seed}`));
  const buildings = [];
  let minH = outer.minH, maxH = outer.maxH, color = outer.color, districtId = outer.id;
  for (const d of districts) {
    const dx = bx - d.cx, dz = bz - d.cz;
    if (dx * dx + dz * dz < d.r * d.r) {
      minH = d.minH; maxH = d.maxH; color = d.color; districtId = d.id;
      break;
    }
  }
  if (water) {
    const hdx = bx - water.cx, hdz = bz - water.cz;
    if (hdx * hdx + hdz * hdz < water.r * water.r) return { buildings };
  }
  const count = 1 + Math.floor(rand() * 3);
  for (let i = 0; i < count; i++) {
    const w = 12 + rand() * 14;
    const d = 12 + rand() * 14;
    const h = minH + rand() * (maxH - minH);
    const x = bx + (rand() - 0.5) * (blockSize - roadWidth - w);
    const z = bz + (rand() - 0.5) * (blockSize - roadWidth - d);
    buildings.push({
      x, z, w, d, h,
      color: color + Math.floor((rand() - 0.5) * 0x101010),
      windows: rand() > 0.3,
      rooftop: rand() > 0.6,
      district: districtId,
    });
  }
  return { buildings };
}

// --- Truman -------------------------------------------------------------
// Mirrors app/truman/town.js generateTown, houses only, one block at
// a time. The fixed features (shops, Henry's house, lighthouse,
// observatory) are home-region landmarks and are NEVER regenerated
// out here. pois: [{ x, z }] (blocks within 40 m stay clear);
// beachX: blocks with centre east of this stay empty (the beach).
export const TRUMAN_HOUSE_COLORS = [0xf5f0e8, 0xe8e0d0, 0xd8e8f0, 0xf0e8d8];

export function generateTownBlock(bx, bz, opts) {
  const { seed = 4242, blockSize, pois, beachX } = opts;
  const rand = mulberry32(hashString32(`truman:block:${bx}:${bz}:${seed}`));
  const houses = [];
  const buildings = [];
  if (beachX !== undefined && bx > beachX) return { houses, buildings };
  for (const poi of pois || []) {
    const dx = bx - poi.x, dz = bz - poi.z;
    if (dx * dx + dz * dz < 40 * 40) return { houses, buildings };
  }
  const count = 2 + Math.floor(rand() * 2);
  for (let i = 0; i < count; i++) {
    const w = 10 + rand() * 4;
    const d = 8 + rand() * 4;
    const h = 6 + rand() * 3;
    const x = bx + (rand() - 0.5) * (blockSize - 20);
    const z = bz + (rand() - 0.5) * (blockSize - 20);
    const color = TRUMAN_HOUSE_COLORS[Math.floor(rand() * TRUMAN_HOUSE_COLORS.length)];
    houses.push({ x, z, w, d, h, color, lawn: true });
    buildings.push({ x, z, w, d });
  }
  return { houses, buildings };
}

// --- Babel district -----------------------------------------------------
// Mirrors app/babel/babel-district.js generateBabelDistrict, one block
// at a time. plazaRadius: blocks within plazaRadius + blockSize/2 of
// the tower stay clear (the plaza). Heights fall with distance from
// the tower, floored at 0.3 — the same distFactor law as home.
export function generateBabelBlock(bx, bz, opts) {
  const { seed = 2026, blockSize, roadWidth, plazaRadius } = opts;
  const rand = mulberry32(hashString32(`babel:block:${bx}:${bz}:${seed}`));
  const buildings = [];
  const distPlaza = Math.sqrt(bx * bx + bz * bz);
  if (distPlaza < plazaRadius + blockSize / 2) return { buildings };
  const count = 1 + Math.floor(rand() * 2);
  for (let i = 0; i < count; i++) {
    const w = 14 + rand() * 16;
    const d = 14 + rand() * 16;
    const distFactor = Math.max(0.3, 1 - distPlaza / 400);
    const h = 18 + rand() * 50 * distFactor + rand() * 20;
    const x = bx + (rand() - 0.5) * (blockSize - roadWidth - w);
    const z = bz + (rand() - 0.5) * (blockSize - roadWidth - d);
    buildings.push({
      x, z, w, d, h,
      color: 0x7d8494 + Math.floor((rand() - 0.5) * 0x0e0e0e),
      windows: rand() > 0.25,
    });
  }
  return { buildings };
}

// --- block ownership ----------------------------------------------------
// Which blocks a chunk owns: blocks whose CENTRE falls inside the
// chunk rect. Block centres sit on the home grid:
// centre = -homeHalf + blockSize/2 + k*blockSize.
export function blocksInChunk(cx, cz, { blockSize, homeHalf }) {
  const { x0, z0, x1, z1 } = chunkBounds(cx, cz);
  const kFor = (edge) => Math.ceil((edge + homeHalf - blockSize / 2) / blockSize);
  const out = [];
  for (let kx = kFor(x0); kx < kFor(x1); kx++) {
    for (let kz = kFor(z0); kz < kFor(z1); kz++) {
      out.push({
        bx: -homeHalf + blockSize / 2 + kx * blockSize,
        bz: -homeHalf + blockSize / 2 + kz * blockSize,
      });
    }
  }
  return out;
}

// A block belongs to the home region (already built by the home
// generator) when its centre sits inside the home square.
export function isHomeBlock(bx, bz, homeHalf) {
  return Math.abs(bx) < homeHalf && Math.abs(bz) < homeHalf;
}
